(function(t){t.JobLabContent=Object.assign(t.JobLabContent||{},{"KK-176":{scenario:{company:"Harborlight Insurance",supervisor:{name:"Bùi Văn Khánh",role:{vi:"Trưởng phòng Giám định Bồi thường",en:"Claims Manager"}},ref_code:"CLM-7742",title:{vi:"Đúng nguyên nhân. Đúng tỷ lệ. Đúng bồi thường.",en:"Right cause. Right ratio. Right settlement."},brief:{vi:"Bạn giám định hồ sơ CLM-7742: cháy kho hàng do chập điện. Thiệt hại do lửa 760 triệu đồng, hàng hư hỏng do nước chữa cháy 480 triệu đồng. Số tiền bảo hiểm 6300 triệu đồng, giá trị thực tế tài sản tại thời điểm tổn thất 8400 triệu đồng, mức khấu trừ 25 triệu đồng mỗi vụ (số liệu mô phỏng). Bản nháp xếp thiệt hại do nước vào rủi ro lũ lụt không được bảo hiểm và chưa áp dụng bảo hiểm dưới giá trị. Hãy sửa hai trường và lập báo cáo.",en:"You are adjusting claim CLM-7742: a warehouse fire caused by an electrical short circuit. Fire damage is 760 million VND and goods damaged by firefighting water 480 million VND. Sum insured 6300 million VND, actual value of the property at the time of loss 8400 million VND, deductible 25 million VND per event (training data). The draft treats the water damage as uninsured flood and ignores underinsurance. Correct both fields and report."},reference_title:{vi:"Biên bản giám định & bảng tính bồi thường đã duyệt · CLM-7742",en:"Approved survey report & settlement worksheet · CLM-7742"},fields:[{id:"CAUSE_CODE",label:{vi:"Nguyên nhân trực tiếp của thiệt hại do nước",en:"Proximate cause of the water damage"},initial:"FLOOD",expected:"FIRE",choices:["FIRE","FLOOD","WATER LEAK"],reference:"Biên bản giám định hiện trường",ref_value:{vi:"Nước từ vòi chữa cháy của lực lượng phòng cháy chữa cháy phun vào kho trong lúc dập lửa",en:"Water from fire brigade hoses sprayed into the warehouse while the fire was being put out"},hint:{vi:"Áp dụng nguyên tắc nguyên nhân trực tiếp: tìm sự kiện khởi phát chuỗi tổn thất.",en:"Apply proximate cause: find the event that set the chain of loss in motion."}},{id:"CLAIM_MVND",label:{vi:"Số tiền bồi thường (triệu đồng)",en:"Claim settlement (million VND)"},initial:"735",expected:"905",reference:"Bảng tính bồi thường",ref_value:{vi:"Tổn thất do lửa 760 + do nước chữa cháy 480; STBH 6300; giá trị thực tế 8400; khấu trừ 25",en:"Fire loss 760 + firefighting water 480; sum insured 6300; actual value 8400; deductible 25"},hint:{vi:"Khi số tiền bảo hiểm thấp hơn giá trị thực tế, bồi thường theo tỷ lệ trước khi trừ mức khấu trừ.",en:"When the sum insured is below actual value, apply the pro rata ratio before the deductible."}}],sop32:{vi:"Bồi thường = tổn thất thuộc phạm vi bảo hiểm x (số tiền bảo hiểm / giá trị thực tế tại thời điểm tổn thất) - mức khấu trừ; nếu số tiền bảo hiểm bằng hoặc cao hơn giá trị thực tế thì không áp tỷ lệ.",en:"Settlement = insured loss x (sum insured / actual value at the time of loss) - deductible; no ratio applies if the sum insured equals or exceeds actual value."},context:{label:"CLAIMS SYSTEM / CLM-7742",metrics:[{label:{vi:"Số tiền bảo hiểm",en:"Sum insured"},value:"6,300,000,000 VND"},{label:{vi:"Giá trị thực tế",en:"Actual value"},value:"8,400,000,000 VND"},{label:{vi:"Mức khấu trừ",en:"Deductible"},value:"25,000,000 VND"}]},crisis:{vi:"Đại diện bên được bảo hiểm đề nghị: “Anh ghi thêm lô hàng ẩm mốc tồn từ năm ngoái vào biên bản thiệt hại do nước, công ty em gửi anh 5% số tiền bồi thường. Đại lý cũng muốn giữ khách lớn này.”",en:"The insured's representative proposes: “Add last year's mouldy stock to the water damage report and my company will give you 5% of the settlement. The agent also wants to keep this big client.”"},options:{safe:{vi:"Từ chối, chỉ ghi nhận thiệt hại đã xác minh bằng chứng từ và hiện trường, báo Trưởng phòng Bồi thường và bộ phận chống trục lợi bảo hiểm bằng văn bản.",en:"Refuse, record only losses verified by documents and site evidence, and report in writing to the Claims Manager and the insurance fraud unit."},shortcut:{vi:"Ghi thêm lô hàng cũ để giữ khách lớn và giải quyết hồ sơ nhanh.",en:"Add the old stock to keep the big client and close the claim fast."},wait:{vi:"Ngừng giám định, chờ đại lý và khách tự thống nhất số liệu.",en:"Stop the adjustment and wait for the agent and the client to agree on figures."}},questions:{vi:["Vì sao thiệt hại do nước chữa cháy thuộc rủi ro cháy và số bồi thường là 905 triệu đồng? Trình bày từng bước tính.","Đề nghị ghi thêm hàng tồn cũ là hành vi gì theo pháp luật kinh doanh bảo hiểm và bạn bảo vệ hồ sơ bằng những bằng chứng nào?"],en:["Why does firefighting water damage fall under the fire peril and why is the settlement 905 million VND? Show each step.","What does adding old stock amount to under insurance law, and which evidence protects the claim file?"]},hints:{vi:["Xác định chuỗi sự kiện từ chập điện, cháy đến phun nước chữa cháy rồi tìm nguyên nhân trực tiếp.","So sánh số tiền bảo hiểm với giá trị thực tế, áp tỷ lệ rồi mới trừ khấu trừ ở SOP mục 3.2.","Đọc SOP mục 4.2: mọi đề nghị khai khống tổn thất phải từ chối và báo bộ phận chống trục lợi."],en:["Trace the chain from short circuit to fire to firefighting water, then find the proximate cause.","Compare the sum insured with actual value, apply the ratio, then the deductible in SOP 3.2.","Re-read SOP 4.2: any request to inflate a loss must be refused and reported to the fraud unit."]}},learning:{summary:{vi:"Chuyên viên giám định bồi thường bảo hiểm khảo sát hiện trường, xác định nguyên nhân và mức độ tổn thất, đối chiếu phạm vi bảo hiểm và điều khoản loại trừ, tính số tiền bồi thường và thương lượng với khách hàng, nhà thầu sửa chữa. Nghề bảo đảm khách hàng được bồi thường công bằng, doanh nghiệp bảo hiểm không bị trục lợi, đòi hỏi kiến thức kỹ thuật, pháp lý, kỹ năng điều tra và tính chính trực.",en:"An insurance claims adjuster surveys the loss site, establishes the cause and extent of damage, checks cover and exclusions, calculates the settlement and negotiates with the insured and repairers. The role ensures fair compensation for customers and protects insurers from fraud, and requires technical and legal knowledge, investigative skills and integrity."},responsibilities:{vi:["Tiếp nhận thông báo tổn thất, hướng dẫn khách hạn chế thiệt hại và giữ hiện trường.","Khảo sát hiện trường, chụp ảnh, thu thập biên bản phòng cháy chữa cháy và chứng từ.","Xác định nguyên nhân trực tiếp, phạm vi bảo hiểm và điều khoản loại trừ áp dụng.","Tính số tiền bồi thường theo giá trị thực tế, bảo hiểm dưới giá trị và mức khấu trừ.","Lập báo cáo giám định, đề xuất phương án và phối hợp thu hồi từ bên thứ ba."],en:["Receive loss notices, guide the insured to mitigate damage and preserve the site.","Survey the site, take photos and collect fire brigade reports and records.","Establish the proximate cause, the cover and applicable exclusions.","Calculate the settlement using actual value, underinsurance and the deductible.","Write the adjustment report, propose the settlement and support recovery from third parties."]},competencies:[{name:{vi:"Điều tra nguyên nhân",en:"Cause investigation"},desc:{vi:"Dựng lại chuỗi sự kiện từ chứng cứ hiện trường để xác định nguyên nhân trực tiếp.",en:"Rebuild the chain of events from site evidence to determine the proximate cause."}},{name:{vi:"Đọc hiểu hợp đồng bảo hiểm",en:"Policy interpretation"},desc:{vi:"Áp dụng đúng phạm vi, rủi ro mở rộng, điều khoản loại trừ và điều kiện đặc biệt.",en:"Apply cover, extensions, exclusions and special conditions correctly."}},{name:{vi:"Định lượng tổn thất",en:"Loss quantification"},desc:{vi:"Xác định giá trị thực tế, khấu hao, tỷ lệ bảo hiểm dưới giá trị và giá trị thu hồi.",en:"Determine actual value, depreciation, underinsurance ratio and salvage."}},{name:{vi:"Đàm phán bồi thường",en:"Settlement negotiation"},desc:{vi:"Giải thích căn cứ bồi thường minh bạch và đạt thỏa thuận công bằng với khách hàng.",en:"Explain the basis of settlement transparently and reach a fair agreement."}},{name:{vi:"Chống trục lợi",en:"Fraud prevention"},desc:{vi:"Nhận diện khai khống, hàng cũ, chứng từ giả và từ chối mọi lợi ích cá nhân.",en:"Detect inflated claims, old stock and fake documents, and refuse any personal benefit."}}],knowledge:{vi:["Luật Kinh doanh bảo hiểm số 08/2022/QH15 và các văn bản hướng dẫn.","Nguyên tắc cơ bản của bảo hiểm: trung thực tuyệt đối, quyền lợi có thể được bảo hiểm, bồi thường, thế quyền, nguyên nhân trực tiếp.","Bảo hiểm dưới giá trị, trên giá trị, bảo hiểm trùng và cách phân bổ bồi thường theo tỷ lệ.","Quy định hiện hành về bảo hiểm cháy, nổ bắt buộc đối với cơ sở có nguy hiểm về cháy, nổ.","Kỹ thuật giám định: thu thập chứng cứ, ảnh hiện trường, biên bản phòng cháy chữa cháy, sổ kho."],en:["The Law on Insurance Business No. 08/2022/QH15 and its guiding documents.","Core principles: utmost good faith, insurable interest, indemnity, subrogation and proximate cause.","Underinsurance, overinsurance, double insurance and pro rata apportionment.","Current compulsory fire and explosion insurance rules for high-risk premises.","Adjustment techniques: evidence collection, site photos, fire brigade reports and stock records."]},tools:["Claims management system","Site survey app (photo, GPS)","Moisture meter & thermal camera","Stock reconciliation sheet","Loss adjustment calculator","Fraud red flag checklist"],tools_en:["Claims management system","Site survey app (photo, GPS)","Moisture meter & thermal camera","Stock reconciliation sheet","Loss adjustment calculator","Fraud red flag checklist"],kpis:{vi:["Thời gian giải quyết hồ sơ bồi thường trung bình.","Tỷ lệ hồ sơ bị khiếu nại hoặc điều chỉnh sau khi duyệt.","Số hồ sơ trục lợi được phát hiện và ngăn chặn.","Độ lệch giữa số dự phòng ban đầu và số bồi thường cuối cùng."],en:["Average claim settlement time.","Share of claims disputed or adjusted after approval.","Fraudulent claims detected and stopped.","Gap between the initial reserve and the final settlement."]},day:[{time:"08:00",vi:"Nhận thông báo tổn thất mới, lập dự phòng ban đầu và lịch khảo sát.",en:"Log new loss notices, set initial reserves and schedule surveys."},{time:"09:30",vi:"Khảo sát hiện trường kho bị cháy, chụp ảnh và lấy lời khai.",en:"Survey the burned warehouse, take photos and interview witnesses."},{time:"13:30",vi:"Đối chiếu sổ kho, hóa đơn với hàng hư hỏng thực tế.",en:"Match stock records and invoices with the actual damaged goods."},{time:"15:00",vi:"Tính bồi thường, áp bảo hiểm dưới giá trị và mức khấu trừ.",en:"Calculate the settlement with underinsurance and the deductible."},{time:"16:30",vi:"Hoàn thiện báo cáo giám định và trao đổi với khách hàng.",en:"Finalise the adjustment report and discuss it with the insured."}],mistakes:{vi:["Loại trừ thiệt hại do nước chữa cháy vì nhầm với rủi ro lũ lụt.","Bỏ qua bảo hiểm dưới giá trị, bồi thường toàn bộ tổn thất khi số tiền bảo hiểm thấp hơn giá trị thực tế.","Ghi nhận hàng tồn cũ hoặc tổn thất không có chứng cứ vào biên bản theo đề nghị của khách."],en:["Excluding firefighting water damage by confusing it with flood.","Ignoring underinsurance and paying the full loss when the sum insured is below actual value.","Recording old stock or unproven losses at the insured's request."]},career:[{vi:"Nhân viên giám định bồi thường",en:"Claims assistant"},{vi:"Chuyên viên giám định bồi thường",en:"Claims adjuster"},{vi:"Chuyên viên giám định cao cấp tài sản kỹ thuật",en:"Senior property and engineering adjuster"},{vi:"Trưởng phòng / Giám đốc Bồi thường",en:"Claims manager / Head of claims"}],glossary:[{term:"Proximate cause",vi:"Nguyên nhân trực tiếp, chủ động và hiệu quả gây ra chuỗi sự kiện dẫn đến tổn thất.",en:"The dominant, effective cause that sets in motion the events leading to a loss."},{term:"Underinsurance",vi:"Bảo hiểm dưới giá trị: số tiền bảo hiểm thấp hơn giá trị thực tế, bồi thường theo tỷ lệ.",en:"Sum insured below actual value, so claims are paid pro rata."},{term:"Deductible",vi:"Mức khấu trừ: phần tổn thất bên được bảo hiểm tự chịu trong mỗi vụ.",en:"The part of each loss borne by the insured."},{term:"Subrogation",vi:"Thế quyền: sau khi bồi thường, doanh nghiệp bảo hiểm được đòi bên thứ ba có lỗi.",en:"After paying, the insurer may recover from the liable third party."},{term:"Utmost good faith",vi:"Trung thực tuyệt đối: các bên phải khai báo đầy đủ, trung thực mọi thông tin trọng yếu.",en:"Both parties must disclose all material facts fully and honestly."}],quiz:[{q:{vi:"Số tiền bảo hiểm 3000 triệu, giá trị thực tế 4000 triệu, tổn thất 800 triệu, không có khấu trừ. Số bồi thường là bao nhiêu?",en:"Sum insured 3000 million, actual value 4000 million, loss 800 million, no deductible. What is the settlement?"},options:{vi:["800 triệu","600 triệu","3000 triệu","200 triệu"],en:["800 million","600 million","3000 million","200 million"]},answer:1,explain:{vi:"Bồi thường = 800 x 3000 / 4000 = 600 triệu đồng do bảo hiểm dưới giá trị.",en:"Settlement = 800 x 3000 / 4000 = 600 million because of underinsurance."}},{q:{vi:"Trong bảo hiểm cháy, thiệt hại do nước dùng để chữa cháy được xử lý thế nào?",en:"Under a fire policy, how is damage from water used to fight the fire treated?"},options:{vi:["Luôn bị loại trừ","Thuộc rủi ro lũ lụt","Chỉ bồi thường khi mua thêm bảo hiểm nước","Được coi là hậu quả của rủi ro cháy theo nguyên nhân trực tiếp"],en:["Always excluded","Treated as flood","Paid only with extra water cover","Treated as a consequence of the fire under proximate cause"]},answer:3,explain:{vi:"Nước chữa cháy là hậu quả tất yếu của việc dập lửa nên thiệt hại thuộc rủi ro cháy.",en:"Firefighting water is a direct consequence of extinguishing the fire, so the damage falls under the fire peril."}},{q:{vi:"Nguyên tắc thế quyền cho phép doanh nghiệp bảo hiểm làm gì?",en:"What does subrogation allow the insurer to do?"},options:{vi:["Đòi bên thứ ba có lỗi sau khi đã bồi thường","Tăng phí khi có tổn thất","Hủy hợp đồng ngay","Từ chối mọi khiếu nại"],en:["Recover from the liable third party after paying","Raise premiums after a loss","Cancel the policy at once","Reject every claim"]},answer:0,explain:{vi:"Thế quyền chuyển quyền đòi bồi hoàn của bên được bảo hiểm sang doanh nghiệp bảo hiểm trong phạm vi đã bồi thường.",en:"Subrogation transfers the insured's recovery rights to the insurer up to the amount paid."}},{q:{vi:"Khách đề nghị chia phần trăm nếu bạn ghi tăng tổn thất. Bạn làm gì?",en:"The insured offers you a percentage if you inflate the loss. What do you do?"},options:{vi:["Đồng ý vì là khách lớn","Ghi tăng một ít cho khách vui","Từ chối, ghi nhận đề nghị và báo bộ phận chống trục lợi","Để đại lý quyết định"],en:["Agree because it is a big client","Inflate it a little to keep them happy","Refuse, record the offer and report it to the fraud unit","Let the agent decide"]},answer:2,explain:{vi:"Khai khống tổn thất là trục lợi bảo hiểm; giám định viên phải từ chối và báo cáo bằng văn bản.",en:"Inflating a loss is insurance fraud; the adjuster must refuse and report it in writing."}}]}}})})(window.KKR);
